<template><section class="playground" :data-playground="lens" :class="{'small-roster':people.length<=30,'exchange-mode':selectableEdges,'readable-labels':readableLabels,'motion-live':generationActive,'swarm-mode':swarm}"><header><div><h3>{{ title }} <span>{{ people.length }}</span></h3><small v-if="!quietHeader||runningCount">{{ savedCount }} saved · {{ runningCount }} requests running</small></div><button v-if="!hideOpenButton" @click="$emit('discussion',lens)">Open {{ title.toLowerCase() }} ↗</button></header><div ref="canvasEl" class="playground-scroll"><svg :viewBox="`0 0 ${layout.width} ${layout.height+(readableLabels?20:0)}`" role="group" :aria-label="title+' playground'">
<defs><filter :id="glowId"><feGaussianBlur stdDeviation="2.7"/></filter></defs>
<g v-if="selectableEdges" class="edge-hit-targets" aria-hidden="true"><path v-for="edge in routed.filter(e=>e.recorded)" :key="edge.id" :data-edge-hit="edge.id" :d="edge.path" @click="$emit('edge-select',edge)"><title>{{ name(edge.source) }} → {{ name(edge.target) }} · recorded {{ edge.kind }}</title></path></g>
<g class="paths"><path v-for="edge in routed" :key="edge.id" :d="edge.path" :data-edge-id="edge.id" :role="selectableEdges&&edge.recorded?'button':undefined" :tabindex="selectableEdges&&edge.recorded?(selectedEventIds.includes(edge.eventId)?0:-1):undefined" :aria-label="edge.recorded?name(edge.source)+' to '+name(edge.target)+' · '+edge.kind:undefined" @click="selectableEdges&&edge.recorded&&$emit('edge-select',edge)" @keydown.enter="selectableEdges&&edge.recorded&&$emit('edge-select',edge)" @keydown.space.prevent="selectableEdges&&edge.recorded&&$emit('edge-select',edge)" :class="[edge.kind,edge.tone,{selected:selectedEventIds.length?selectedEventIds.includes(edge.eventId):focus===edge.source||focus===edge.target,active:activeEdges.some(e=>e.id===edge.id)}]"><title>{{ edge.kind==='evidence'?hubLabel+' shared context':name(edge.source)+' → '+name(edge.target)+' · recorded '+edge.kind }}</title></path></g>
<g v-if="evidence" class="hub" :transform="`translate(${layout.width/2},${layout.height/2})`"><circle r="20"/><path d="M-7-9h10l5 5v13H-7zM3-9v5h5M-3 1h7M-3 5h7"/><text y="34" text-anchor="middle">{{ hubLabel }}</text></g>
<g v-for="person in layout.nodes" :key="person.id" :transform="`translate(${person.x},${person.y})`" class="agent-node" :class="[state(person),{selected:focus===person.id,responding:active?.author===person.id,receiving:active?.recipients.includes(person.id),partner:spotlightPeople.includes(person.id)&&focus!==person.id,sender:senderId===person.id,receiver:receiverIds.includes(person.id)}]" role="button" :tabindex="selectableEdges?(focus===person.id||!focus&&person.id===people[0]?.id?0:-1):0" :aria-label="person.label+' · '+person.status" :aria-pressed="focus===person.id" :style="swarm?{'--agent-color':agentColor(person.id)}:undefined" :data-agent-id="person.id" @click="$emit('select',person.id)" @keydown.enter="$emit('select',person.id)" @keydown.space.prevent="$emit('select',person.id)"><title>{{ person.label }} · {{ person.status }}{{ person.behavior||person.strategy?' · '+(person.behavior||person.strategy):'' }}</title><circle v-if="swarm" class="node-hit" r="14"/><circle class="halo" :r="swarm?11:23"/><circle class="orb" :r="swarm?4:17"/><foreignObject v-if="!swarm" x="-11" y="-11" width="22" height="22"><AnalystRoleIcon :person="person"/></foreignObject><text v-if="lens==='traders'&&!swarm" class="member-number" text-anchor="middle" x="17" y="-15">{{ number(person.id) }}</text><circle v-if="state(person)==='output_saved'&&!swarm" class="saved-dot" cx="13" cy="13" r="4"/><text v-if="!swarm||focus===person.id||active?.author===person.id" class="node-name" :y="swarm?19:30" text-anchor="middle"><tspan v-for="(line,index) in labelLines(person)" :key="index" x="0" :dy="index?13:0">{{ line }}</tspan></text></g>
<g v-for="edge in activeEdges" :key="active.id+edge.id" class="packets" :class="{reply:relationTone(active)==='reply',disagreement:relationTone(active)==='disagreement'}"><circle r="6" class="packet-glow" :filter="`url(#${glowId})`"><animateMotion :path="edge.path" :dur="motionDuration+'s'" repeatCount="1" fill="freeze"/></circle><circle r="3" class="packet"><animateMotion :path="edge.path" :dur="motionDuration+'s'" repeatCount="1" fill="freeze"/></circle></g>
</svg></div><footer><span v-if="swarm&&(localFocus||active)">{{ name(localFocus||active.author) }}<template v-if="!localFocus&&active?.recipients.length"> → {{ active.recipients.map(name).join(', ') }}</template></span><span v-else>{{ active?.replay?'Replaying a saved message':active?'New recorded message':localFocus?'Selected participant’s recorded connections':'Recorded connections · select a participant' }}</span><small v-if="lens==='traders'" title="Trader identities share batched model calls; saved message activity is not an independent live process.">Shared batched requests</small></footer></section></template>
<script setup>
import {computed,ref,onMounted,onBeforeUnmount,watch,nextTick} from 'vue'
import {stableAgentLayout,relationTone,participantOrdinal,revealParticipantScroll} from '../utils/agentInteraction.mjs'
import AnalystRoleIcon from './AnalystRoleIcon.vue'
import {playgroundConnections,playgroundPath,participantShortLabel} from '../utils/playground.mjs'
const props=defineProps({people:Array,events:Array,title:String,lens:String,seed:String,focus:String,active:Object,evidence:Boolean,generationActive:Boolean,swarm:Boolean,motionDuration:{type:Number,default:1.2},senderId:String,receiverIds:{type:Array,default:()=>[]},spotlightPeople:{type:Array,default:()=>[]},readableLabels:Boolean,quietHeader:Boolean,minimumHeight:{type:Number,default:210},selectableEdges:Boolean,selectedEventIds:{type:Array,default:()=>[]},hideOpenButton:Boolean,hubLabel:{default:'Shared evidence'}})
defineEmits(['select','discussion','edge-select'])
const canvasEl=ref(null),canvasWidth=ref(600);let observer
onMounted(()=>{observer=new ResizeObserver(entries=>{canvasWidth.value=Math.max(260,Math.floor(entries[0]?.contentRect.width||600))});if(canvasEl.value)observer.observe(canvasEl.value)})
onBeforeUnmount(()=>observer?.disconnect())
const layout=computed(()=>{const scale=props.swarm?(canvasWidth.value<380?2.8:1.8):1,scene=stableAgentLayout(props.people,props.seed,canvasWidth.value*scale,props.minimumHeight*scale);return {width:scene.width/scale,height:scene.height/scale,nodes:scene.nodes.map(person=>({...person,x:person.x/scale,y:person.y/scale}))}}),glowId=computed(()=>'packet-glow-'+props.lens+'-'+String(props.seed).replace(/[^\w-]/g,''))
const colors=['#f4935e','#78c8ce','#9296d9','#79b7a0','#cea66b','#c792b0']
const agentColor=id=>{let hash=2166136261;for(const char of String(id))hash=Math.imul(hash^char.charCodeAt(0),16777619)>>>0;return colors[hash%colors.length]}
const state=p=>p.lifecycle?.state||p.state||'unknown'
const savedCount=computed(()=>props.people.filter(p=>state(p)==='output_saved').length),runningCount=computed(()=>props.people.filter(p=>state(p)==='running').length)
const routed=computed(()=>{const anchors=new Map(layout.value.nodes.map(n=>[n.id,n]));anchors.set('evidence-hub',{x:layout.value.width/2,y:layout.value.height/2});return playgroundConnections(props.events,props.people,{evidence:props.evidence}).map(e=>{const selected=props.events.find(event=>props.selectedEventIds.includes(event.id)&&event.author===e.source&&event.recipients.includes(e.target)&&event.kind===e.kind);const recorded=selected||props.events.find(event=>event.id===e.eventId);return {...e,tone:relationTone(recorded),eventId:selected?.id||e.eventId,path:playgroundPath(anchors.get(e.source),anchors.get(e.target))}})})
const activeEdges=computed(()=>props.active?routed.value.filter(e=>e.source===props.active.author&&props.active.recipients.includes(e.target)&&e.kind===props.active.kind||!props.active.recipients.length&&e.kind==='evidence'&&e.target===props.active.author):[])
watch(()=>[props.focus,canvasWidth.value],async()=>{await nextTick();const container=canvasEl.value,node=layout.value.nodes.find(p=>p.id===props.focus),svg=container?.querySelector('svg');if(!container||!node||!svg)return;const scale=svg.getBoundingClientRect().height/(layout.value.height+(props.readableLabels?20:0));container.scrollTop=revealParticipantScroll(container.scrollTop,container.clientHeight,node.y,scale,Math.max(0,container.scrollHeight-container.clientHeight))},{flush:'post'})
const localFocus=computed(()=>props.people.some(p=>p.id===props.focus)?props.focus:'')
const name=id=>props.people.find(p=>p.id===id)?.label||id
const number=id=>participantOrdinal(props.people.find(p=>p.id===id))
const shortLabel=p=>props.readableLabels&&props.lens==='specialists'?({ict_liquidity:'Liquidity',ict_fvg:'Fair-value gap',ict_orderblocks:'Order blocks',support_resistance:'Support & resistance',price_action:'Price action',trend:'Trend',momentum:'Momentum',mean_reversion:'Mean reversion',overextension:'Pullback',potential_top:'Potential top',potential_bottom:'Potential bottom',volume:'Volume',classical:'Wyckoff / patterns',risk:'Risk'}[p.id]||participantShortLabel(p,props.lens)):participantShortLabel(p,props.lens)
const labelLines=p=>{const text=shortLabel(p);if(!props.readableLabels||text.length<=15)return [text];const spaces=[...text.matchAll(/ /g)].map(m=>m.index),split=spaces.sort((a,b)=>Math.abs(a-text.length/2)-Math.abs(b-text.length/2))[0];return split?[text.slice(0,split),text.slice(split+1)]:[text]}
</script>
<style scoped>
.playground{border:1px solid #e0e7ef;background:white;border-radius:9px;overflow:hidden;margin-bottom:12px}.playground>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 15px}.playground h3{font-size:15px;font-weight:600;margin:0}.playground h3 span{font-size:11px;font-weight:500;background:#f0f3f7;border-radius:10px;padding:2px 7px;margin-left:5px}.playground header small{font-size:10px;color:#7b8ba0;display:block;margin-top:4px}.playground header button{font-size:11px;color:#a73508;border:0;background:none;cursor:pointer}.playground-scroll{max-height:270px;overflow-y:auto;background:radial-gradient(ellipse at 50% 50%,#fff6ef55,transparent 60%);overflow:auto}.playground svg{display:block;width:100%;min-height:170px}.paths path{fill:none;stroke:#99afca;stroke-width:1.2;opacity:.45;vector-effect:non-scaling-stroke}.paths .evidence{stroke:#d9c1af;stroke-dasharray:3 7;opacity:.28}.paths .question{stroke:#db9165}.paths .reply,.paths .cross_reply,.paths .response{stroke:#88afd8}.paths .selected{stroke:#f08249;opacity:.72;stroke-width:1.4}.paths .reply.selected,.paths .cross_reply.selected,.paths .response.selected{stroke:#5e9cda}.paths .active{stroke:#ff5b14;opacity:1;stroke-width:2}.paths .reply.active,.paths .cross_reply.active,.paths .response.active{stroke:#428de1}.hub circle{fill:#fff9f3;stroke:#f0dccc;stroke-width:1}.hub path{fill:none;stroke:#c88c64;stroke-width:1.2}.hub text{font-size:10px;fill:#a68771}.agent-node{cursor:pointer;outline:none}.agent-node .orb{animation:spawn .4s ease-out 1;fill:#f4f7fb;stroke:#8fa8c4;stroke-width:1.2}.agent-node .halo{fill:transparent;stroke:transparent;stroke-width:1.6}.agent-node.output_saved .orb{fill:#f0faf5;stroke:#6eab86}.agent-node.running .orb{fill:#fff4eb;stroke:#ff6826}.agent-node.failed .orb{fill:#fff0ed;stroke:#ca8975}.agent-node.selected .halo,.agent-node:focus .halo{stroke:#ff6b2a;fill:#fff4ea66}.agent-node.responding .halo{stroke:#ff895b;animation:response 1.2s ease-out 1}.agent-node.running .halo{stroke:#ffd5c1;animation:working 2s ease-in-out infinite}.agent-node foreignObject{color:#4d685e;pointer-events:none}.agent-node foreignObject svg{min-height:0;width:22px;height:22px}.number{font-size:11px;fill:#475d7b;pointer-events:none}.node-name{font-size:10px;fill:#425b78;pointer-events:none}.saved-dot{fill:#60a87c;stroke:white;stroke-width:1.5}.packet{fill:#ff6627;stroke:white;stroke-width:1}.packets.reply .packet{fill:#4b98e7}.packets.reply .packet-glow{fill:#7fb7fa}.packet-glow{fill:#ff934d;opacity:.7}.playground footer{border-top:1px solid #f0f3f7;padding:8px 14px;display:flex;justify-content:space-between;gap:12px;font-size:10px;color:#8692a3}.playground footer small{font-size:9px}@keyframes spawn{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:scale(1)}}@keyframes response{0%{opacity:1;transform:scale(.8)}100%{opacity:0;transform:scale(1.6)}}@keyframes working{50%{opacity:.4;transform:scale(1.15)}}@media(max-width:620px){.playground svg{min-width:0}.playground-scroll{overflow-x:auto;max-height:280px}.playground header{padding:10px 12px}.playground footer{flex-wrap:wrap;gap:4px}}@media(prefers-reduced-motion:reduce){.packets{display:none}.agent-node .orb{animation:none}.agent-node.responding .halo,.agent-node.running .halo{animation:none}}

.playground-scroll{scrollbar-width:thin;scrollbar-color:#cbd7e4 transparent}.playground-scroll::-webkit-scrollbar{width:5px;height:5px}.playground-scroll::-webkit-scrollbar-track{background:transparent}.playground-scroll::-webkit-scrollbar-thumb{background:#cbd7e4;border-radius:5px}.playground-scroll::-webkit-scrollbar-thumb:hover{background:#afc0d3}@media(min-width:621px){.small-roster .playground-scroll{max-height:none;overflow-y:visible}}

.exchange-mode .paths path{opacity:.15}.exchange-mode .paths .selected{opacity:1;stroke-width:2}.exchange-mode .paths .active{opacity:1}.exchange-mode .paths path[role=button]{cursor:pointer;pointer-events:none;stroke-width:2.2}.exchange-mode .paths path[role=button]:focus{outline:none;opacity:1;stroke-width:3}.exchange-mode .paths .evidence{opacity:.12}

.edge-hit-targets path{fill:none;stroke:transparent;stroke-width:12;pointer-events:stroke;vector-effect:non-scaling-stroke;cursor:pointer}.exchange-mode .paths path,.exchange-mode .hub,.exchange-mode .packets{pointer-events:none}.readable-labels .node-name{font-size:11px}

.agent-node .orb,.agent-node.running .halo{animation:none}.motion-live .agent-node.running .orb{animation:spawn .4s ease-out 1}.motion-live .agent-node.running .halo{animation:working 2.6s ease-in-out infinite}.agent-node.output_saved .orb{fill:#fff;stroke:#aebfce}.agent-node .orb{fill:#fff;filter:drop-shadow(0 2px 3px #2f4a6710)}.agent-node.selected .orb{fill:#fff1e7;stroke:#f27032;stroke-width:1.8}.agent-node.partner .orb{fill:#eef6ff;stroke:#78a8d5}.agent-node.receiving .halo{stroke:#67a4df;animation:receive 1.2s ease-out 1}.paths .disagreement.selected,.paths .disagreement.active{stroke:#9462b9}.paths path{transition:opacity .2s,stroke .2s}.playground>header{border-bottom:1px solid #edf1f5}.node-name{font-weight:500}.saved-dot{fill:#78988a}@keyframes receive{0%{opacity:1;transform:scale(.8)}100%{opacity:0;transform:scale(1.7)}}@media(prefers-reduced-motion:reduce){.motion-live .agent-node .orb,.motion-live .agent-node.running .halo,.agent-node.receiving .halo{animation:none}.paths path{transition:none}}

.agent-node.sender .orb{fill:#fff1e7;stroke:#f07635;stroke-width:1.8}.agent-node.receiver .orb{fill:#edf6ff;stroke:#6d9fcc;stroke-width:1.8}

.member-number{font-size:9px;fill:#8b9bad}.agent-node.receiver .member-number{fill:#5686b5}

.packets.disagreement .packet{fill:#9766bc}.packets.disagreement .packet-glow{fill:#b794d2}

.paths path:not(.selected):not(.active){stroke:#a6b7c9;opacity:.25}.exchange-mode .paths path:not(.selected):not(.active){stroke:#afbdcb;opacity:.12}.paths .question.selected,.paths .question.active{stroke:#f07c3a}.paths .reply.selected,.paths .reply.active,.paths .response.selected,.paths .response.active{stroke:#5a94c7}
</style>
